# minutes from 00:00
to_min = fun(t) {
  parts = text.split(t, ":")
  return number.parse(parts[0]) * 60 + number.parse(parts[1])
}

# possible starts in minutes: 9:00 to 16:00 step 30
starts = [540, 570, 600, 630, 660, 690, 720, 750, 780, 810, 840, 870, 900, 930, 960]

dates = ["2026-06-15", "2026-06-16", "2026-06-17", "2026-06-18", "2026-06-19"]

# For each date index 0..4, build combined busy for all users
# Check each start: slot [s, s+60) overlaps any busy?

# overlapping: not (end <= start_busy or start >= end_busy)
# busy if slot_start < busy_end and slot_end > busy_start

results = for di in list.range(0, 5) {
  date = dates[di]
  # collect all busy intervals for this day across users
  all_busy = fold acc = [] for u in avails {
    day = u.days[di]
    intervals = for b in day.busy {
      return { start: to_min(b.start), end: to_min(b.end) }
    }
    return acc + intervals
  }
  # find free starts
  free = for s in starts {
    slot_end = s + 60
    conflicts = fold c = 0 for b in all_busy {
      overlap = s < b.end and slot_end > b.start
      return c + (1 if overlap else 0)
    }
    skip if conflicts > 0
    return s
  }
  return { date: date, free: free }
}

# earliest: first date with non-empty free, take first start
earliest = fold found = null for r in results {
  return found if found != null else (
    { date: r.date, start: r.free[0] } if r.free != [] else null
  )
}

# format time
fmt = fun(m) {
  h = number.floor(m / 60)
  mi = m - h * 60
  hs = text.slice("0" + json.encode(h), -2, 100)
  ms = text.slice("0" + json.encode(mi), -2, 100)
  return hs + ":" + ms + ":00Z"
}

start_str = earliest.date + "T" + fmt(earliest.start)
end_str = earliest.date + "T" + fmt(earliest.start + 60)

return { start: start_str, end: end_str, debug: results, earliest: earliest }

